//! CH-Trie (coordinate hash trie) — a faithful Rust translation of the C
//! `chtrie` library (`chtrie_alloc` / `chtrie_walk` / `chtrie_del` /
//! `chtrie_free`).
//!
//! The C API signals errors through `errno`; here the two failure classes are
//! modeled as [`ChTrieError::Range`] (C `ERANGE`) and
//! [`ChTrieError::Capacity`] (C `ENOMEM` on node-pool exhaustion).
//! `chtrie_free` is replaced by Rust's drop semantics.

pub mod chtrie;

pub use crate::chtrie::{ChTrie, ChTrieError};
=====CHTRIE=====
//! Translation of `src/chtrie.c` / `src/chtrie.h`.
//!
//! Mapping of the C API:
//! - `chtrie_alloc(n, m)`            → [`ChTrie::alloc`]
//! - `chtrie_walk(tr, from, sym, cr)`→ [`ChTrie::walk`]
//! - `chtrie_del(tr, from, sym)`     → [`ChTrie::del`]
//! - `chtrie_free(tr)`               → `Drop` (automatic)

use std::error::Error;
use std::fmt;

/// Errors corresponding to the C library's `errno` signaling.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ChTrieError {
    /// `chtrie_alloc` was given `n`/`m` beyond `i32::MAX`, or
    /// `ecap = (n-1) + (n-1)/3` would overflow `i32` (C `ERANGE`).
    Range,
    /// `walk` with `creat` was requested but the node pool is exhausted
    /// (C `ENOMEM`).
    Capacity,
}

impl Error for ChTrieError {}

impl fmt::Display for ChTrieError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ChTrieError::Range => write!(f, "chtrie: argument out of range"),
            ChTrieError::Capacity => write!(f, "chtrie: node pool exhausted"),
        }
    }
}

/// A single edge in a hash-bucket chain (C `struct chtrie_edge`).
struct Edge {
    next: Option<Box<Edge>>,
    from: i32,
    sym: i32,
    to: i32,
}

/// A coordinate hash trie (C `chtrie`).
///
/// All fields are private; the C struct's public internals are replaced by
/// the `alloc` / `walk` / `del` methods. Memory is released automatically
/// when the value is dropped (C `chtrie_free`).
pub struct ChTrie {
    /// Ha...

//! Port of `tests/test.c` — the 14-case CH-Trie integration test.

use chtrie::ChTrie;

const N: usize = 65536;
const M: usize = 256;

/// Shared state mirroring the C test's globals: the trie plus the
/// `term[N]` (termination flag) and `nchild[N]` (child count) arrays.
struct State {
    tr: ChTrie,
    term: Vec<bool>,
    nchild: Vec<i32>,
}

impl State {
    fn new() -> Self {
        let tr = ChTrie::alloc(N, M).expect("chtrie_alloc");
        State {
            tr,
            term: vec![false; N],
            nchild: vec![0; N],
        }
    }

    /// C `add(char *s)`.
    fn add(&mut self, s: &str) {
        let mut it = 0;
        for c in s.bytes() {
            if self.tr.walk(it, c as i32, false).expect("chtrie_walk").is_none() {
                self.nchild[it as usize] += 1;
            }
            it = self
                .tr
                .walk(it, c as i32, true)
                .expect("chtrie_walk")
                .expect("chtrie_walk");
        }
        self.term[it as usize] = true;
    }

    /// C `del(char *s)`.
    fn del(&mut self, s: &str) {
        let mut nodes: Vec<i32> = Vec::new();
        let mut symbs: Vec<i32> = Vec::new();
        let mut it = 0;
        let mut found = true;
        for c in s.bytes() {
            nodes.push(it);
            symbs.push(c as i32);
            match self.tr.walk(it, c as i32, false).expect("chtrie_walk") {
                Some(x) => it = x,
                None => {
                    found = false;
                    break;
                }
            }
        }
        if !found || !self.term[it as usize] {
            return;
        }
        self.term[it as usize] = false;
        while it > 0 && !self.term[it as usize] && self.nchild[it as usize] == 0 {
            let n = nodes.len();
            self.tr.del(nodes[n - 1], symbs[n - 1]);
            it = nodes[n - 1];
            self.nchild[it as usize] -= 1;
        }
    }

